import{_ as a,o as r,c as t,a0 as l}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"KernelSU とは?","description":"","frontmatter":{},"headers":[],"relativePath":"ja_JP/guide/what-is-kernelsu.md","filePath":"ja_JP/guide/what-is-kernelsu.md"}'),o={name:"ja_JP/guide/what-is-kernelsu.md"};function n(s,e,i,h,d,u){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="kernelsu-とは" tabindex="-1">KernelSU とは? <a class="header-anchor" href="#kernelsu-とは" aria-label="Permalink to &quot;KernelSU とは?&quot;">​</a></h1><p>KernelSU は Android GKI デバイスのための root ソリューションです。カーネルモードで動作し、カーネル空間で直接ユーザー空間アプリに root 権限を付与します。</p><h2 id="機能" tabindex="-1">機能 <a class="header-anchor" href="#機能" aria-label="Permalink to &quot;機能&quot;">​</a></h2><p>KernelSU の最大の特徴は、<strong>カーネルベース</strong>であることです。KernelSU はカーネルモードで動作するため、今までにないカーネルインターフェイスを提供できます。例えば、カーネルモードで任意のプロセスにハードウェアブレークポイントを追加できる、誰にも気づかれずに任意のプロセスの物理メモリにアクセスできる、カーネル空間で任意のシステムコールを傍受できる、などです。</p><p>さらに、KernelSU は <a href="./metamodule.html">metamodule システム</a> を提供しています。これはモジュール管理のためのプラグ可能なアーキテクチャです。従来の root ソリューションがマウントロジックをコアに組み込むのとは異なり、KernelSU はこの作業を metamodule に委任します。これにより、metamodule (<a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a>など) をインストールして、<code>/system</code>パーティションや他のパーティションへのsystemless変更を提供できます。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><p>こちらをご覧ください: <a href="./installation.html">インストール方法</a></p><h2 id="ビルド方法" tabindex="-1">ビルド方法 <a class="header-anchor" href="#ビルド方法" aria-label="Permalink to &quot;ビルド方法&quot;">​</a></h2><p><a href="./../../guide/how-to-build.html">ビルドするには</a></p><h2 id="ディスカッション" tabindex="-1">ディスカッション <a class="header-anchor" href="#ディスカッション" aria-label="Permalink to &quot;ディスカッション&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const _=a(o,[["render",n]]);export{c as __pageData,_ as default};
